  "sbsCalcFormulaNote": { "fa": "فرمول تعیین حجم نمونه (حد اطمینان ۹۵٪): N = K² × (۱−P) / (S² × P) — طبق راهنمای HSE. بعد از محاسبه، هدف نهایی را برای پیمانکار ارسال می‌کنید تا نمونه‌برداری واقعی را انجام دهد.", "en": "Sample-size formula (95% confidence): N = K² × (1−P) / (S² × P) — per the HSE guide. After calculating, you send the final target to the contractor to carry out the actual sampling." },
