  "dbeeErrSaveWeightNoAccess": { "fa": "ذخیره انجام نشد: دسترسی شما برای تغییر وزن‌دهی این شرکت تأیید نشد. لطفاً مطمئن شوید با نقش کارفرما یا ادمین شرکت وارد شده‌اید.", "en": "Not saved: your access to change this company's weighting was not confirmed. Please make sure you are signed in with the employer or company-admin role." },
