  // DBEE weights manager
  "dbeeWmLoading": { "fa": "در حال بارگذاری...", "en": "Loading..." },
  "dbeeWmTitle": { "fa": "وزن‌دهی موتور اثربخشی Barrier (DBEE)", "en": "Barrier Effectiveness Engine Weighting (DBEE)" },
  "dbeeWmIntro": { "fa": "این وزن‌ها مخصوص شرکت شماست و روی محاسبه‌ی امتیاز اثربخشی همه‌ی Barrierهای BowTie اثر می‌گذارد. عدد ۱ یعنی خنثی؛ بیشتر از ۱ یعنی همان عامل جریمه‌ی بیشتری ایجاد کند، کمتر از ۱ یعنی جریمه‌اش تخفیف بخورد.", "en": "These weights are specific to your company and affect the effectiveness-score calculation for every BowTie barrier. 1 means neutral; above 1 means the factor imposes a larger penalty, below 1 means its penalty is reduced." },
  "dbeeWmGuideHint": { "fa": "برای توضیح هر عامل، روی آیکون", "en": "For an explanation of each factor, click the" },
  "dbeeWmGuideHint2": { "fa": "کنارش بزنید.", "en": "icon next to it." },
  "dbeeWmGroupMain": { "fa": "عوامل اصلی محاسبه", "en": "Main calculation factors" },
  "dbeeWmGroupSources": { "fa": "وزن هر منبع داده", "en": "Weight of each data source" },
  "dbeeWmFactorGuideTitle": { "fa": "توضیح این عامل", "en": "Explain this factor" },
  "dbeeGuideFrequency": { "fa": "تعداد دفعات تکرار یک شاهد ضعف (مثلاً چند بار این Barrier در آنومالی‌های اخیر ذکر شده). مثال: اگر یک Barrier در ۵ آنومالی جدا دیده شود، وزن بیشتر یعنی این تکرار جریمه‌ی سنگین‌تری ایجاد کند.", "en": "How many times a weakness signal recurs (e.g. how often this barrier is mentioned in recent anomalies). Example: if a barrier appears in 5 separate anomalies, a higher weight makes that repetition impose a heavier penalty." },
  "dbeeGuideSeverity": { "fa": "شدت خودِ رویدادی که ضعف Barrier را نشان داده (مثلاً سطح ریسک آنومالی: بالا/متوسط/پایین، یا ناتوان‌کننده‌بودن حادثه). وزن بیشتر یعنی رویدادهای شدید، تأثیر بیشتری روی افت امتیاز بگذارند.", "en": "The severity of the event that revealed the barrier weakness (e.g. anomaly risk level high/medium/low, or whether an incident was disabling). A higher weight lets severe events have more impact on the score drop." },
  "dbeeGuideRecurrence": { "fa": "تکرارشدنِ مشابه در بازه‌ی کوتاه (مثلاً ۳ آنومالی مرتبط در ۹۰ روز اخیر). این جدا از «فراوانی کلی» است — تمرکزش روی الگوی اخیر و پشت‌سرهم است، نه کل تاریخچه.", "en": "Similar repetition within a short window (e.g. 3 related anomalies in the last 90 days). This is separate from \"overall frequency\" — it focuses on the recent, consecutive pattern, not the whole history." },
  "dbeeGuideCriticality": { "fa": "ضریبی که بر اساس سطح بحرانی‌بودن خودِ Barrier (پایین/متوسط/بالا، همان فیلدی که در خودِ BowTie تعیین می‌شود) کل جریمه‌ی نهایی را تشدید یا تخفیف می‌دهد. مثال: یک Barrier با بحرانی‌بودن «بالا»، با وزن بیشتر، حتی با شواهد کم هم امتیازش سریع‌تر افت می‌کند.", "en": "A coefficient that, based on the barrier's own criticality level (low/medium/high, the field set in the BowTie itself), amplifies or reduces the final total penalty. Example: a barrier with \"high\" criticality and a higher weight drops in score faster even with little evidence." },
  "dbeeGuideRecency": { "fa": "وزن شواهد جدید در برابر شواهد قدیمی. طبق طراحی موتور، شواهد ثبت‌شده در ۹۰ روز اخیر همیشه اثر بیشتری از شواهد قدیمی‌تر دارند؛ این عامل شدت آن تفاوت را تنظیم می‌کند.", "en": "The weight of recent evidence versus old evidence. By the engine's design, evidence from the last 90 days always has more effect than older evidence; this factor tunes how large that difference is." },
  "dbeeGuideSrcAnomaly": { "fa": "سهم داده‌ی «مدیریت عدم انطباق‌ها (Anomaly)» در محاسبه — آنومالی‌هایی که مستقیماً به این Barrier متصل شده‌اند.", "en": "The contribution of \"Non-Conformance Management (Anomaly)\" data — anomalies directly linked to this barrier." },
  "dbeeGuideSrcCapa": { "fa": "سهم داده‌ی «اقدامات اصلاحی (CAPA)» — اقدام‌های باز یا منقضی‌شده‌ی متصل به این Barrier؛ اقدام منقضی‌شده همیشه جریمه‌ی بیشتری دارد.", "en": "The contribution of \"Corrective Actions (CAPA)\" data — open or expired actions linked to this barrier; an expired action always carries a bigger penalty." },
  "dbeeGuideSrcIncident": { "fa": "سهم داده‌ی «حوادث» — فقط حوادثی که کاربر HSE صراحتاً به این Barrier مرتبط کرده است (نه هر حادثه‌ای).", "en": "The contribution of \"Incidents\" data — only incidents the HSE user has explicitly linked to this barrier (not every incident)." },
  "dbeeGuideSrcTripod": { "fa": "سهم داده‌ی «تحلیل ریشه‌ای Tripod Beta» — فقط تحلیل‌هایی که صراحتاً به این Barrier مرتبط شده‌اند؛ نتیجه‌ی «رد شده» توسط کارفرما سیگنال قوی‌تری است.", "en": "The contribution of \"Tripod Beta root-cause analysis\" data — only analyses explicitly linked to this barrier; an employer \"rejected\" outcome is a stronger signal." },
  "dbeeGuideSrcSbs": { "fa": "سهم داده‌ی «نمونه‌برداری رفتار ایمنی (SBS)» — مشاهدات رفتار ناایمن در دسته‌هایی که به این Barrier نگاشت شده‌اند.", "en": "The contribution of \"Safety Behavior Sampling (SBS)\" data — unsafe-behavior observations in categories mapped to this barrier." },
  "dbeeGuideSrcHseClimate": { "fa": "سهم داده‌ی «جو ایمنی سازمانی (HSE Climate)» — میانگین پایین ابعادی از پرسشنامه که به این Barrier نگاشت شده‌اند.", "en": "The contribution of \"organizational safety climate (HSE Climate)\" data — low averages of questionnaire dimensions mapped to this barrier." },
  "dbeeGuideSrcAccidentProneness": { "fa": "سهم داده‌ی «استعداد حادثه‌پذیری» — فقط ارزیابی‌های سطح «بالا»/«بسیار بالا» برای مشاغلی که به این Barrier نگاشت شده‌اند.", "en": "The contribution of \"accident proneness\" data — only \"high\"/\"very high\" level assessments for jobs mapped to this barrier." },

