  "dbeeTmTitle": { "fa": "Mapping منابع غیرمستقیم به Barrier", "en": "Mapping Indirect Sources to Barriers" },
  "dbeeTmIntro": { "fa": "برای منابعی که رابطه‌ی مستقیمی به Barrier ندارند (SBS، HSE Climate، استعداد حادثه‌پذیری)، اینجا مشخص می‌کنید کدام دسته/بُعد/شغل به کدام Barrier مرتبط است. این ارتباط هیچ‌وقت خودکار ایجاد نمی‌شود.", "en": "For sources with no direct relation to a barrier (SBS, HSE Climate, accident proneness), here you specify which category/dimension/job is linked to which barrier. This mapping is never created automatically." },
  "dbeeTmLoading": { "fa": "در حال بارگذاری...", "en": "Loading..." },
