  "dbeeTmErrAllRequired": { "fa": "انتخاب هر سه‌ی منبع، BowTie و Barrier الزامی است", "en": "Selecting all three — the source, BowTie, and Barrier — is required" },
  "dbeeTmDeleteConfirm": { "fa": "این ارتباط حذف شود؟", "en": "Delete this mapping?" },
