  "dbeeBmpTitle": { "fa": "Barrierهای مرتبط (برای موتور اثربخشی DBEE)", "en": "Related Barriers (for the DBEE effectiveness engine)" },
  "dbeeBmpIntro": { "fa": "اگر این رویداد نشان‌دهنده‌ی ضعف یکی از Barrierهای BowTie است، آن را اینجا مشخص کنید — این ارتباط مستقیماً در محاسبه‌ی اثربخشی همان Barrier لحاظ می‌شود.", "en": "If this event indicates a weakness in one of the BowTie barriers, specify it here — this mapping is directly included in that barrier's effectiveness calculation." },
  "dbeeBmpNoneYet": { "fa": "هنوز هیچ Barrier ای به این رویداد مرتبط نشده است.", "en": "No barrier has been linked to this event yet." },
